export type ToastNotificationsConfig = {
  key: string;
  enabled?: boolean;
  metadata?: Record<string, unknown>;
};

export function createToastNotificationsConfig(config: ToastNotificationsConfig) {
  return {
    key: config.key,
    enabled: config.enabled ?? true,
    metadata: config.metadata ?? {},
  };
}

export const toastNotificationsChecks = [
  "Render the provider once in the app layout",
  "Keep API errors generic in user-facing messages",
  "Log detailed failures server-side without exposing secrets",
] as const;

"use client";

import { Toaster, toast } from "sonner";

type ToastInput = {
  title: string;
  description?: string;
};

export function StackFoundryToastProvider({
  position = "bottom-right",
}: {
  position?: "bottom-left" | "bottom-center" | "bottom-right";
}) {
  return <Toaster position={position} />;
}

export function notifySuccess({ title, description }: ToastInput) {
  toast.success(title, { description });
}

export function notifyError({ title, description }: ToastInput) {
  toast.error(title, { description });
}

export function notifyInfo({ title, description }: ToastInput) {
  toast(title, { description });
}

"use client";

import { StackFoundryToastProvider, notifySuccess } from "@/components/stackfoundry/toast-notifications";

export default function ToastNotificationsDemo() {
  return (
    <StackFoundryToastProvider>
      <section className="rounded-lg border p-6">
        <h2 className="font-semibold">Action feedback</h2>
        <p className="mt-2 text-sm text-muted-foreground">
          Toasts appear after the provider is mounted in your app layout.
        </p>
        <button
          type="button"
          className="mt-4 rounded-md bg-primary px-4 py-2 text-sm text-primary-foreground"
          onClick={() => notifySuccess({ title: "Saved", description: "Your changes are live." })}
        >
          Show success toast
        </button>
      </section>
    </StackFoundryToastProvider>
  );
}
